<script setup lang="ts">
import { computed, ref } from 'vue'
import { usePmisStore, ROLES } from '@/stores/pmis'
import { newInspection, inspectionTemplates, type Inspection } from '@/lib/inspections'
import plan from '@/data/assessmentPlan.json'
import { PARTS } from '@/data/parts'
const pm=usePmisStore()
const emit=defineEmits<{openTask:[id:string];openDocument:[id:string];openAsset:[id:string];openIssues:[]}>()
const template=ref('資料完整性'), draft=ref(newInspection()), selected=ref(false), filter=ref('全部'), search=ref(''), notice=ref(''), failed=ref(false), review=ref(''), defectOwner=ref(''), defectDue=ref('')
const current=computed(()=>pm.state.inspections.find(x=>x.id===draft.value.id))
const locked=computed(()=>['待複核','已接受'].includes(current.value?.status??''))
const rows=computed(()=>pm.state.inspections.filter(i=>(filter.value==='全部'||i.status===filter.value)&&`${i.title} ${i.inspector} ${i.asset}`.includes(search.value)))
function open(i?:Inspection){draft.value=i?JSON.parse(JSON.stringify(i)):newInspection(template.value);selected.value=true;notice.value='';review.value='';defectOwner.value='';defectDue.value=''}
function run(fn:()=>void){try{fn();failed.value=!!pm.error;notice.value=pm.error||'已更新本機查驗紀錄'}catch(e){failed.value=true;notice.value=e instanceof Error?e.message:'操作失敗'}}
function save(){draft.value.id=pm.saveInspection(draft.value);draft.value=JSON.parse(JSON.stringify(current.value))}
function submit(){save();pm.submitInspection(draft.value.id);draft.value=JSON.parse(JSON.stringify(current.value))}
function decide(accept:boolean){pm.reviewInspection(draft.value.id,accept,review.value);draft.value=JSON.parse(JSON.stringify(current.value))}
function defect(item:string){if(!locked.value)save();pm.inspectionDefect(draft.value.id,item,defectOwner.value,defectDue.value);draft.value=JSON.parse(JSON.stringify(current.value))}
function addItem(){draft.value.items.push({id:crypto.randomUUID(),label:'',result:'未查驗',note:'',issueId:''})}
function exportRecord(){if(!current.value)return;const url=URL.createObjectURL(new Blob([JSON.stringify({project:pm.project,record:current.value},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`inspection-${current.value.id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>
<template><section class="inspections"><div class="top"><label>角色視角<select v-model="pm.role"><option v-for="r in ROLES" :key="r">{{r}}</option></select></label><label>操作人<input v-model="pm.actor" placeholder="填寫紀錄人姓名" /></label><label>新清單範本<select v-model="template"><option v-for="(_,name) in inspectionTemplates" :key="name">{{name}}</option></select></label><button @click="open()">＋ 建立查驗</button></div><p class="muted">範本是待專案調整的紀錄欄位，非核定查驗標準。請填寫正式圖說、程序及接受準則來源。資料僅存本機，不代表現場已完工或正式簽認。</p><p v-if="pm.error" class="error">{{pm.error}}</p><p v-if="notice" :class="failed?'error':'success'" role="status">{{notice}}</p><div class="filters"><input v-model="search" placeholder="搜尋查驗／人員／模型" /><select v-model="filter" aria-label="查驗狀態篩選"><option v-for="s in ['全部','草稿','待複核','已接受','退回']" :key="s">{{s}}</option></select><span>{{rows.length}} 筆 · {{pm.state.inspections.filter(i=>i.status==='待複核').length}} 筆待複核</span></div><div class="layout"><aside><p v-if="!rows.length">尚無符合條件的查驗紀錄。</p><button v-for="i in rows" :key="i.id" class="record" @click="open(i)"><b>{{i.title}}</b><small>{{i.date}} · {{i.status}}</small><small>{{i.inspector}} → {{i.reviewer}}</small></button></aside><main v-if="selected"><h3>{{draft.id?'查驗詳情':'新增查驗紀錄'}} · {{current?.status??'草稿'}}</h3><form @submit.prevent="run(save)"><fieldset :disabled="locked"><div class="grid"><label class="wide">查驗名稱<input v-model="draft.title" required /></label><label>查驗日期<input type="date" v-model="draft.date" required /></label><label>查驗人<input v-model="draft.inspector" required /></label><label>複核人<input v-model="draft.reviewer" required /></label><label>模型群組<select v-model="draft.asset"><option value="">未關聯</option><option v-for="p in PARTS" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>WBS<select v-model="draft.task"><option value="">未關聯</option><option v-for="t in plan.tasks" :key="t.code" :value="t.code">{{t.code}} {{t.name}}</option></select></label><label>交付文件<select v-model="draft.document"><option value="">未關聯</option><option v-for="d in plan.documents" :key="d.code">{{d.code}}</option></select></label><label class="wide">查驗依據與接受準則<textarea v-model="draft.basis" required placeholder="圖說／程序編號、版本與專案核定條件" /></label></div><h3>查驗項目</h3><article v-for="(item,index) in draft.items" :key="item.id"><label>{{index+1}}. 查驗內容<input v-model="item.label" required /></label><label>結果<select v-model="item.result"><option v-for="r in ['未查驗','合格','不合格','不適用']" :key="r">{{r}}</option></select></label><label>觀察／不合格或不適用原因<textarea v-model="item.note" /></label><small v-if="item.issueId">缺失：{{item.issueId}} · {{pm.state.issues.find(i=>i.id===item.issueId)?.status}}</small></article><button type="button" @click="addItem">＋ 新增查驗項目</button><label>證據與紀錄位置<textarea v-model="draft.evidence" placeholder="照片或測試紀錄連結、文件編號與版本；此欄僅保存文字，不上傳檔案" /></label><button>儲存草稿</button></fieldset></form><div class="actions"><button v-if="!locked&&draft.id" @click="run(submit)">儲存並送複核</button><button v-if="draft.id" @click="exportRecord">匯出已儲存查驗紀錄</button><button v-if="draft.asset" @click="emit('openAsset',draft.asset)">3D 定位</button><button v-if="draft.task" @click="emit('openTask',draft.task)">WBS {{draft.task}}</button><button v-if="draft.document" @click="emit('openDocument',draft.document)">{{draft.document}}</button></div><section v-if="draft.id"><h3>缺失追蹤</h3><p>不合格項目可轉為缺失議題。送複核可保留不合格結果供審閱，但接受前必須完成修正、重新送審，且關聯缺失已結案。</p><div class="grid" v-if="draft.items.some(i=>i.result==='不合格'&&!i.issueId)"><label>缺失責任人<input v-model="defectOwner" /></label><label>改善期限<input type="date" v-model="defectDue" /></label></div><article v-for="i in draft.items.filter(i=>i.result==='不合格'||i.issueId)" :key="i.id"><b>{{i.label}}</b><button v-if="!i.issueId&&current?.status!=='已接受'" @click="run(()=>defect(i.id))">轉缺失議題</button><template v-if="i.issueId"><p>{{i.issueId}} · {{pm.state.issues.find(x=>x.id===i.issueId)?.status}}</p><button @click="emit('openIssues')">前往議題協調</button></template></article><h3>複核與退回</h3><p v-if="current?.submittedBy">送審紀錄：{{current.submittedBy}}</p><p v-if="current?.reviewNote">最近複核：{{current.reviewedBy}} · {{current.reviewNote}}</p><template v-if="locked"><label>複核說明<textarea v-model="review" /></label><button v-if="current?.status==='待複核'" @click="run(()=>decide(true))">記錄接受</button><button @click="run(()=>decide(false))">退回修正</button></template><details><summary>查驗異動紀錄</summary><article v-for="a in pm.state.audit.filter(a=>a.target===draft.id)" :key="a.id"><b>{{a.action}}</b><small>{{a.actor}} · {{a.at}}</small><p>{{a.note}}</p></article></details></section></main><div v-else><h3>查驗 → 缺失 → 複核</h3><p>先選範本建立查驗紀錄，再填寫專案核定依據。各項結果可追溯至證據、工項及模型群組。</p></div></div></section></template>
<style scoped>
.inspections{padding:16px;font-size:12px;color:var(--text);line-height:1.7}.top,.filters,.actions{display:flex;flex-wrap:wrap;gap:8px;align-items:end}.filters{margin:16px 0}.layout{display:grid;grid-template-columns:185px minmax(0,1fr);gap:16px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.wide{grid-column:1/-1}label{display:flex;flex-direction:column;gap:5px;margin:10px 0}input,select,textarea,button{font:inherit;background:var(--panel-solid);color:var(--text);border:1px solid var(--line);border-radius:6px;padding:8px;min-width:0;max-width:100%;box-sizing:border-box}textarea{min-height:65px;resize:vertical}button{cursor:pointer;margin:3px}button:hover{background:#43c7ff15;border-color:#43c7ff}.record{display:block;width:100%;text-align:left;padding:12px}small,.record b{display:block}small,.muted{color:var(--muted)}fieldset{border:0;padding:0;min-width:0}fieldset:disabled{opacity:.7}article{padding:12px;border:1px solid var(--line);border-radius:8px;margin:10px 0}p{white-space:pre-wrap;overflow-wrap:anywhere}.error{color:#ffaaaa}.success{color:#75d5ac}summary{cursor:pointer;color:#85d9ff}details{margin:20px 0}@media(max-width:1000px){.layout{grid-template-columns:1fr}aside{max-height:200px;overflow:auto}.grid{grid-template-columns:1fr}}
</style>
